import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static String solve(int N, int X, int[] A) {for (int i = 0; i < N; i++) {if (A[i] == X) {return "YES";}}return "NO";}public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line = br.readLine();if (line == null) return;StringTokenizer st = new StringTokenizer(line);int N = Integer.parseInt(st.nextToken());int X = Integer.parseInt(st.nextToken());int[] A = new int[N];st = new StringTokenizer(br.readLine());for (int i = 0; i < N; i++) {A[i] = Integer.parseInt(st.nextToken());}System.out.println(solve(N, X, A));}}